from fractions import Fraction
import math

def root(q):
    # √q for a Fraction q >= 0, simplified: √18 = 3√2, √(13/4) = √13/2
    if q == 0:
        return "0"
    n = q.numerator * q.denominator
    f = 1
    for d in range(2, math.isqrt(n) + 1):
        if n % (d * d) == 0:
            f = d
    c = Fraction(f, q.denominator)
    rest = n // (f * f)
    if rest == 1:
        return f"{c}"
    top = f"√{rest}"
    if c.numerator != 1:
        top = f"{c.numerator}√{rest}"
    if c.denominator == 1:
        return top
    return f"{top}/{c.denominator}"

n = int(input())
for i in range(n):
    D = int(input())
    E = int(input())
    F = int(input())
    h = Fraction(-D, 2)
    k = Fraction(-E, 2)
    r2 = h * h + k * k - F
    if r2 > 0:
        print(f"center ({h}, {k}), radius {root(r2)}")
    elif r2 == 0:
        print(f"point ({h}, {k})")
    else:
        print("no points")

