    if c.denominator == 1:
        return top
    return f"{top}/{c.denominator}"

def conic(case, P, Q):
    print(case)
    if P > 0 and Q > 0:
        if P == Q:
            print(f"  equal denominators: a circle of radius {root(P)}")
            return
        if P > Q:
            a2, b2, axis = P, Q, "x"
        else:
            a2, b2, axis = Q, P, "y"
        c2 = a2 - b2
        print(f"  both terms add: an ellipse, a² = {a2} is the bigger one, under {axis}²")
        print(f"  c² = a² - b² = {a2} - {b2} = {c2}")
    else:
        if P > 0:
            a2, b2, axis = P, -Q, "x"
        else:
            a2, b2, axis = Q, -P, "y"
        c2 = a2 + b2
        print(f"  a minus sign: a hyperbola, a² = {a2} is under the positive {axis}² term")
        print(f"  c² = a² + b² = {a2} + {b2} = {c2}")
    print(f"  a = {root(a2)}, b = {root(b2)}, c = {root(c2)}")
    if axis == "x":
        print(f"  vertices (±{root(a2)}, 0), foci (±{root(c2)}, 0)")
    else:
        print(f"  vertices (0, ±{root(a2)}), foci (0, ±{root(c2)})")
    if P < 0 or Q < 0:
        if axis == "x":
            slope = root(Fraction(b2, a2))
        else:
            slope = root(Fraction(a2, b2))
        print(f"  asymptotes y = ±({slope})x")

conic("Example 1, a wide ellipse: x²/25 + y²/9 = 1", 25, 9)
conic("Example 2, a tall ellipse: x²/16 + y²/25 = 1", 16, 25)
conic("Example 3, c isn't whole: x²/9 + y²/4 = 1", 9, 4)
conic("Example 5, a circle: x²/16 + y²/16 = 1", 16, 16)
conic("Example 6, opening left and right: x²/9 - y²/16 = 1", 9, -16)
conic("Example 7, opening up and down: y²/9 - x²/16 = 1", -16, 9)

