from fractions import Fraction

def square(v, h):
    # (v - h)² the way you'd write it by hand
    if h == 0:
        return f"{v}²"
    if h > 0:
        return f"({v} - {h})²"
    return f"({v} + {-h})²"

def line(v, h):
    if h == 0:
        return v
    if h > 0:
        return f"({v} - {h})"
    return f"({v} + {-h})"

def times(c, s):
    # c times s, leaving out a 1: 4(x - 2)², (y + 1)², -8(y - 1)
    if c == 1:
        return s
    if c == -1:
        return f"-{s}"
    return f"{c}{s}"

def identify(case, A, C, D, E, F):
    print(case)
    if A == 0:
        k = Fraction(-E, 2 * C)
        h = Fraction(C * k * k - F, D)
        print(f"  A = 0, a parabola: {times(C, square('y', k))} = {times(-D, line('x', h))}, vertex ({h}, {k})")
        return
    if C == 0:
        h = Fraction(-D, 2 * A)
        k = Fraction(A * h * h - F, E)
        print(f"  C = 0, a parabola: {times(A, square('x', h))} = {times(-E, line('y', k))}, vertex ({h}, {k})")
        return
    h = Fraction(-D, 2 * A)
    k = Fraction(-E, 2 * C)
    G = A * h * h + C * k * k - F
    if C > 0:
        left = f"{times(A, square('x', h))} + {times(C, square('y', k))}"
    else:
        left = f"{times(A, square('x', h))} - {times(-C, square('y', k))}"
    print(f"  complete both squares: {left} = {G}")
    if A * C < 0:
        if G == 0:
            print(f"  opposite signs, 0 on the right: two lines through ({h}, {k})")
        else:
            print(f"  opposite signs: a hyperbola with center ({h}, {k})")
    elif G * A < 0:
        print("  same signs, but the right side has the other sign: no points")
    elif G == 0:
        print(f"  same signs, 0 on the right: the single point ({h}, {k})")
    elif A == C:
        print(f"  A = C: a circle with center ({h}, {k}) and r² = {G / A}")
    else:
        print(f"  same signs, A ≠ C: an ellipse with center ({h}, {k})")

identify("Example 1: 2x² + 2y² - 8x + 12y - 6 = 0", 2, 2, -8, 12, -6)
identify("Example 2: 4x² + 9y² - 16x + 18y - 11 = 0", 4, 9, -16, 18, -11)
identify("Example 3: 9x² - 4y² - 36x - 8y - 4 = 0", 9, -4, -36, -8, -4)
identify("Example 4: y² - 4x - 6y + 17 = 0", 0, 1, -4, -6, 17)
identify("Example 5: x² + 6x + 8y + 1 = 0", 1, 0, 6, 8, 1)
identify("Example 6: x² + y² - 6x - 8y = 0", 1, 1, -6, -8, 0)
identify("Example 7: x² + 4y² - 2x + 8y + 5 = 0", 1, 4, -2, 8, 5)
identify("Example 8: x² + 2y² + 4x + 12 = 0", 1, 2, 4, 0, 12)
identify("Example 9: x² - y² - 2x + 1 = 0", 1, -1, -2, 0, 1)

