for i in range(n):
    A = int(input())
    C = int(input())
    D = int(input())
    E = int(input())
    F = int(input())
    if A == 0 or C == 0:
        name = "parabola"
    else:
        h = Fraction(-D, 2 * A)
        k = Fraction(-E, 2 * C)
        G = A * h * h + C * k * k - F
        if A * C < 0:
            if G == 0:
                name = "two lines"
            else:
                name = "hyperbola"
        elif G * A < 0:
            name = "no points"
        elif G == 0:
            name = "point"
        elif A == C:
            name = "circle"
        else:
            name = "ellipse"
    print(name)
